ST.html:p:
IF FirstScan THEN
    LOOP_4750_03_TRIP        := TRUE;
    LOOP_4712_02_TRIP        := TRUE;
    LOOP_104_01_TRIP         := TRUE;
    SAFE_STATE               := TRUE;
    TV_4750_03_Out           := 32767;
    PVA_4712_02_Out          := 6554;
    SV_104_01_Out            := 6554;
    MV_FC_HS_4750_Out        := 6554;
    MV_H_1007_N1_INLET_Out   := 6554;
    MV_H_1007_N4_OUTLET_Out  := 6554;
    CV_66KL21_80_Out         := 6554;
    BV_73KH12_25_1_Out       := 6554;
    BV_73KH12_25_2_Out       := 6554;
    BV_73KH12_50_1_Out       := 6554;
    BV_73KH12_50_2_Out       := 6554;
    BV_MNc_47125_1_Out       := 6554;
    XV_75SA21_80             := FALSE;
    TV_Integral              := 50.0;
    PVA_Integral             := 50.0;
    PI_4712_01_HH_Active     := FALSE;
    PI_4712_01_LL_Active     := FALSE;
    FirstScan                := FALSE;
    RETURN;
END_IF;

PI_4712_01_Scaled := ((INT_TO_REAL(PI_4712_01_Raw) - 6554.0) / (32767.0 - 6554.0)) * 190.0;

(* HH latch — set above HH_SP, reset only when ack'd and value returned below threshold *)
IF PI_4712_01_Scaled > PI_4712_01_HH_SP THEN
    PI_4712_01_HH_Set := TRUE;
ELSIF PI_4712_01_Scaled <= (PI_4712_01_HH_SP - PI_4712_01_Deadband) THEN
    PI_4712_01_HH_Set := FALSE;
END_IF;
PI_4712_01_HH_Rst := PI_4712_01_HH_Ack AND NOT PI_4712_01_HH_Set;
IF PI_4712_01_HH_Set THEN
    PI_4712_01_HH_Active := TRUE;
ELSIF PI_4712_01_HH_Rst THEN
    PI_4712_01_HH_Active := FALSE;
END_IF;

(* H alarm — non-latching with deadband *)
IF PI_4712_01_Scaled > PI_4712_01_H_SP THEN
    PI_4712_01_H := TRUE;
ELSIF PI_4712_01_Scaled <= (PI_4712_01_H_SP - PI_4712_01_Deadband) THEN
    PI_4712_01_H := FALSE;
END_IF;

(* L alarm — non-latching with deadband *)
IF PI_4712_01_Scaled < PI_4712_01_L_SP THEN
    PI_4712_01_L := TRUE;
ELSIF PI_4712_01_Scaled >= (PI_4712_01_L_SP + PI_4712_01_Deadband) THEN
    PI_4712_01_L := FALSE;
END_IF;

(* LL latch — set below LL_SP, reset only when ack'd and value returned above threshold *)
IF PI_4712_01_Scaled < PI_4712_01_LL_SP THEN
    PI_4712_01_LL_Set := TRUE;
ELSIF PI_4712_01_Scaled >= (PI_4712_01_LL_SP + PI_4712_01_Deadband) THEN
    PI_4712_01_LL_Set := FALSE;
END_IF;
PI_4712_01_LL_Rst := PI_4712_01_LL_Ack AND NOT PI_4712_01_LL_Set;
IF PI_4712_01_LL_Set THEN
    PI_4712_01_LL_Active := TRUE;
ELSIF PI_4712_01_LL_Rst THEN
    PI_4712_01_LL_Active := FALSE;
END_IF;

(* Map PI-4712.01 alarm states to PICSA-4712.02 safety deviation flags *)
PICSA_4712_02_HH := PI_4712_01_HH_Active;
PICSA_4712_02_LL := PI_4712_01_LL_Active;

(* Safety trip latches per MUST 29 *)
IF TICSA_4750_03_HH OR TICSA_4750_03_LL THEN
    LOOP_4750_03_TRIP := TRUE;
ELSIF LOOP_4750_03_TRIP AND MANUAL_RESET
      AND NOT TICSA_4750_03_HH AND NOT TICSA_4750_03_LL THEN
    LOOP_4750_03_TRIP := FALSE;
END_IF;

IF PICSA_4712_02_HH OR PICSA_4712_02_LL THEN
    LOOP_4712_02_TRIP := TRUE;
ELSIF LOOP_4712_02_TRIP AND MANUAL_RESET
      AND NOT PICSA_4712_02_HH AND NOT PICSA_4712_02_LL THEN
    LOOP_4712_02_TRIP := FALSE;
END_IF;

IF SV_104_01_HH OR SV_104_01_LL THEN
    LOOP_104_01_TRIP := TRUE;
ELSIF LOOP_104_01_TRIP AND MANUAL_RESET
      AND NOT SV_104_01_HH AND NOT SV_104_01_LL THEN
    LOOP_104_01_TRIP := FALSE;
END_IF;

SAFE_STATE := ESTOP OR LOOP_4750_03_TRIP OR LOOP_4712_02_TRIP OR LOOP_104_01_TRIP;

IF NOT SAFE_STATE THEN
    (* Temperature control loop TV-4750.03 — fail-open valve, PI controller *)
    TV_Error    := TV_SP - 60.0;
    TV_Integral := TV_Integral + (TV_Ki * TV_Error);
    IF TV_Integral > 100.0 THEN
        TV_Integral := 100.0;
    ELSIF TV_Integral < 0.0 THEN
        TV_Integral := 0.0;
    END_IF;
    TV_Output_Pct := (TV_Kp * TV_Error) + TV_Integral;
    IF TV_Output_Pct > 100.0 THEN
        TV_Output_Pct := 100.0;
    ELSIF TV_Output_Pct < 0.0 THEN
        TV_Output_Pct := 0.0;
    END_IF;
    TV_4750_03_Out := REAL_TO_INT(6554.0 + (TV_Output_Pct / 100.0) * (32767.0 - 6554.0));

    (* Pressure control loop PVA-4712.02 — PI controller on PI-4712.01 *)
    PVA_Error    := PVA_SP - PI_4712_01_Scaled;
    PVA_Integral := PVA_Integral + (PVA_Ki * PVA_Error);
    IF PVA_Integral > 100.0 THEN
        PVA_Integral := 100.0;
    ELSIF PVA_Integral < 0.0 THEN
        PVA_Integral := 0.0;
    END_IF;
    PVA_Output_Pct := (PVA_Kp * PVA_Error) + PVA_Integral;
    IF PVA_Output_Pct > 100.0 THEN
        PVA_Output_Pct := 100.0;
    ELSIF PVA_Output_Pct < 0.0 THEN
        PVA_Output_Pct := 0.0;
    END_IF;
    PVA_4712_02_Out := REAL_TO_INT(6554.0 + (PVA_Output_Pct / 100.0) * (32767.0 - 6554.0));

    (* MV-FC-HS-4750: hand-switch driven fail-closed valve *)
    IF HS_4750_01 THEN
        MV_FC_HS_4750_Pct := 100.0;
    ELSE
        MV_FC_HS_4750_Pct := 0.0;
    END_IF;
    MV_FC_HS_4750_Out       := REAL_TO_INT(6554.0 + (MV_FC_HS_4750_Pct / 100.0) * (32767.0 - 6554.0));

    (* Auxiliary valves — hold at 50% nominal until dedicated loops are defined *)
    SV_104_01_Out           := REAL_TO_INT(6554.0 + (50.0 / 100.0) * (32767.0 - 6554.0));
    MV_H_1007_N1_INLET_Out  := REAL_TO_INT(6554.0 + (50.0 / 100.0) * (32767.0 - 6554.0));
    MV_H_1007_N4_OUTLET_Out := REAL_TO_INT(6554.0 + (50.0 / 100.0) * (32767.0 - 6554.0));
    CV_66KL21_80_Out        := REAL_TO_INT(6554.0 + (50.0 / 100.0) * (32767.0 - 6554.0));
    BV_73KH12_25_1_Out      := REAL_TO_INT(6554.0 + (50.0 / 100.0) * (32767.0 - 6554.0));
    BV_73KH12_25_2_Out      := REAL_TO_INT(6554.0 + (50.0 / 100.0) * (32767.0 - 6554.0));
    BV_73KH12_50_1_Out      := REAL_TO_INT(6554.0 + (50.0 / 100.0) * (32767.0 - 6554.0));
    BV_73KH12_50_2_Out      := REAL_TO_INT(6554.0 + (50.0 / 100.0) * (32767.0 - 6554.0));
    BV_MNc_47125_1_Out      := REAL_TO_INT(6554.0 + (50.0 / 100.0) * (32767.0 - 6554.0));
    XV_75SA21_80            := HS_4750_01;
ELSE
    TV_4750_03_Out          := 32767;
    PVA_4712_02_Out         := 6554;
    SV_104_01_Out           := 6554;
    MV_FC_HS_4750_Out       := 6554;
    MV_H_1007_N1_INLET_Out  := 6554;
    MV_H_1007_N4_OUTLET_Out := 6554;
    CV_66KL21_80_Out        := 6554;
    BV_73KH12_25_1_Out      := 6554;
    BV_73KH12_25_2_Out      := 6554;
    BV_73KH12_50_1_Out      := 6554;
    BV_73KH12_50_2_Out      := 6554;
    BV_MNc_47125_1_Out      := 6554;
    XV_75SA21_80            := FALSE;
END_IF;

System_Alarm :=
    PI_4712_01_HH_Active OR PI_4712_01_LL_Active OR
    PI_4712_01_H         OR PI_4712_01_L          OR
    LOOP_4750_03_TRIP    OR LOOP_4712_02_TRIP      OR
    LOOP_104_01_TRIP     OR SAFE_STATE;
